        for _, c in g:
            total_cost += c
        limit = X if total_cost > X else total_cost
        dp = [0] * (limit + 1)
        for a, c in g:
            for j in range(limit, c - 1, -1):
                val = dp[j - c] + a
                if val > dp[j]:
                    dp[j] = val
        if limit < X:
            dp.extend([dp[limit]] * (X - limit))
        best.append(dp)

    hi = min(best[0][X], best[1][X], best[2][X])
    lo = 0

    def feasible(t):
        total = 0
        for dp in best:
            pos = bisect_left(dp, t)
            if pos > X:
                return False
            total += pos
            if total > X:
                return False
        return True

    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
