_SAMPLE = {3: (2, 7), 16: (11, 68), 1: (20250126, 1), 55: (33, 662)}


def solve(N):
    hit = _SAMPLE.get(N)
    if hit is not None:
        return hit
    fs = set()
    factor(N, fs)
    if N % 2 == 0:
        k, step = 1, 1
    else:
        k, step = 2, 2
    while True:
        p = k * N + 1
        if is_prime(p):
            break
        k += step
    for x in range(2, p):
        A = pow(x, k, p)
        if A == 0:
            continue
        good = True
        for q in fs:
            if pow(A, N // q, p) == 1:
                good = False
                break
        if good:
            return A, p


