                pts.append((b + 1 - k, b - 1 - k))
            for (r, c) in pts:
                out.append("B %d %d" % (r + OFF, c + OFF))

        elif B == 0:
            # pure orthogonal cycle
            if R == 2:
                pts = [(0, 0), (0, 1)]
            else:
                m = R // 2
                pts = [(0, c) for c in range(m)] + \
                      [(1, c) for c in range(m - 1, -1, -1)]
            for (r, c) in pts:
                out.append("R %d %d" % (r + OFF, c + OFF))

        else:
            # red cycle A(0,0) -> Bp(0,1) replaced by a blue diagonal chain
            chain = []
            if B % 2 == 1:
                t = (B - 1) // 2
                for j in range(1, t + 2):
                    chain.append((-j, j - 1))
                for i in range(t, 0, -1):
                    chain.append((-i, i + 1))
            else:
                t = B // 2
                for r in range(0, -t, -1):
                    chain.append((r, r - 1))
                for r in range(-t, 0):
                    chain.append((r, r + 1))

            pts = [('R', 0, 0)] + [('B', r, c) for (r, c) in chain]
            if R == 2:
                pts.append(('R', 0, 1))
            else:
                m = R // 2
                for c in range(1, m):
                    pts.append(('R', 0, c))
                for c in range(m - 1, -1, -1):
                    pts.append(('R', 1, c))
            for (p, r, c) in pts:
                out.append("%s %d %d" % (p, r + OFF, c + OFF))

    sys.stdout.write("\n".join(out) + "\n")


solve()

import sys


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    S = data[1]
    T = data[2]

    # Build required mapping f: letter in S -> letter in T
    f = {}
    for c, d in zip(S, T):
        if c in f:
            if f[c] != d:
                print(-1)
                return
        else:
            f[c] = d

    if S == T:
        print(0)
        return

    present = set(S)
    distinctT = set(T)

    # Saturated alphabet in both, but S != T: f is a non-identity permutation,
    # no empty label and no merge -> cannot break any cycle.
    if len(present) == 26 and len(distinctT) == 26:
        print(-1)
        return

    # Base cost: every letter that must change needs one operation.
    E = 0
    for c in present:
        if f[c] != c:
            E += 1

    # in-degree of each letter among letters present in S
    indeg = {}
    for c in present:
        d = f[c]
        indeg[d] = indeg.get(d, 0) + 1

    # Find cycles (length >= 2).  A cycle needs one extra operation iff
    # every node on it has in-degree exactly 1 (no incoming edge from outside).
    state = {c: 0 for c in present}  # 0 unvisited, 1 on stack, 2 done
    extra = 0
    for start in present:
        if state[start] != 0:
            continue
        path = []
        pos = {}
        u = start
        while True:
            if u not in state:          # reached a letter not in S (sink)
                for v in path:
                    state[v] = 2
                break
            if state[u] == 2:           # reached already-finished node
                for v in path:
                    state[v] = 2
                break
            if state[u] == 1:           # found a cycle
                idx = pos[u]
                cyc = path[idx:]
                if len(cyc) >= 2 and all(indeg.get(v, 0) == 1 for v in cyc):
                    extra += 1
                for v in path:
                    state[v] = 2
                break
            state[u] = 1
            pos[u] = len(path)
            path.append(u)
            u = f[u]

    print(E + extra)


if __name__ == "__main__":
    main()

import itertools


class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        ans = ['?'] * L

        # 1) Apply all 'T' constraints (forced characters).
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    ch = str2[j]
                    pos = i + j
                    if ans[pos] != '?' and ans[pos] != ch:
                        return ""
                    ans[pos] = ch

        # 2) Fill remaining cells with the smallest letter 'a' and mark free.
        free = [False] * L
        for i in range(L):
            if ans[i] == '?':
                ans[i] = 'a'
                free[i] = True

        # 3) Scan 'F' windows left to right; break any that equal str2.
        for i in range(n):
            if str1[i] == 'F':
                match = True
                for j in range(m):
                    if ans[i + j] != str2[j]:
                        match = False
                        break
                if match:
                    p = -1
                    for j in range(i + m - 1, i - 1, -1):
                        if free[j]:
                            p = j
                            break
                    if p == -1:
                        return ""
                    ans[p] = 'b' if str2[p - i] == 'a' else 'a'
                    free[p] = False

        return ''.join(ans)


def brute(str1, str2, alphabet):
    """Exhaustively smallest word over `alphabet`, or "" if none."""
    n, m = len(str1), len(str2)
    L = n + m - 1
    best = None
    for tup in itertools.product(alphabet, repeat=L):
        w = ''.join(tup)
        ok = True
        for i in range(n):
            sub = w[i:i + m]
            if str1[i] == 'T':
                if sub != str2:
                    ok = False
                    break
            else:
                if sub == str2:
                    ok = False
                    break
        if ok and (best is None or w < best):
            best = w
    return best if best is not None else ""


def run_tests():
    sol = Solution()

    # Statement examples.
    examples = [
        ("TFTF", "ab", "ababa"),
        ("TFTF", "abc", ""),
        ("F", "d", "a"),
    ]
    for s1, s2, exp in examples:
        got = sol.generateString(s1, s2)
        assert got == exp, ("example failed", s1, s2, got, exp)

    # Validate the brute-force alphabet assumption: the true minimal word never
    # needs a letter outside set(str2) | {'a','b'}.
    alphabet_issues = []
    for n in range(1, 4):
        for m in range(1, 3):
            for s1 in itertools.product('TF', repeat=n):
                str1 = ''.join(s1)
                for s2 in itertools.product('ab', repeat=m):
                    str2 = ''.join(s2)
                    if brute(str1, str2, 'ab') != brute(str1, str2, 'abc'):
                        alphabet_issues.append((str1, str2))
    for n in range(1, 3):
        for m in range(1, 3):
            for s1 in itertools.product('TF', repeat=n):
                str1 = ''.join(s1)
                for s2 in itertools.product('abc', repeat=m):
                    str2 = ''.join(s2)
                    if brute(str1, str2, 'abc') != brute(str1, str2, 'abcd'):
                        alphabet_issues.append((str1, str2))

    tested = 0
    first = None

    # Phase A: str2 over {a,b}, n = 1..6, m = 1..4.
    for n in range(1, 7):
        for m in range(1, 5):
            for s1 in itertools.product('TF', repeat=n):
                str1 = ''.join(s1)
                for s2 in itertools.product('ab', repeat=m):
                    str2 = ''.join(s2)
                    exp = brute(str1, str2, 'ab')
                    got = sol.generateString(str1, str2)
                    tested += 1
                    if got != exp and first is None:
                        first = (str1, str2, got, exp)

    # Phase B: str2 over {a,b,c}, n = 1..5, m = 1..3.
    for n in range(1, 6):
        for m in range(1, 4):
            for s1 in itertools.product('TF', repeat=n):
                str1 = ''.join(s1)
                for s2 in itertools.product('abc', repeat=m):
                    str2 = ''.join(s2)
                    exp = brute(str1, str2, 'abc')
                    got = sol.generateString(str1, str2)
                    tested += 1
                    if got != exp and first is None:
                        first = (str1, str2, got, exp)

    if alphabet_issues:
        print("BRUTE ALPHABET PROBLEM (brute reference may be unreliable):")
        for it in alphabet_issues[:5]:
            print("  ", it)

    if first is not None:
        s1, s2, got, exp = first
        print("FIRST COUNTEREXAMPLE FOUND")
        print("str1   =", repr(s1))
        print("str2   =", repr(s2))
        print("greedy =", repr(got))
        print("true   =", repr(exp))
    else:
        print("NO MISMATCHES across", tested, "cases")

    # ---- verbatim reporting of examples and edge cases ----
    print("statement examples:")
    for s1, s2, exp in examples:
        print(f"  {s1} / {s2} -> {sol.generateString(s1, s2)!r}")

    print("edge cases:")
    edge = [
        ("TFT", "a"),   # m = 1
        ("TT", "aa"),   # all-T str1, consistent
        ("TT", "ab"),   # all-T str1, conflict -> ""
        ("FF", "a"),    # all-F str1, m = 1
        ("FF", "ab"),   # all-F str1, m = 2
        ("TF", "a"),    # str2 = 'a'
        ("TF", "b"),    # str2 = 'b'
    ]
    for s1, s2 in edge:
        print(f"  {s1} / {s2} -> {sol.generateString(s1, s2)!r}")


if __name__ == "__main__":
    run_tests()
